    "journey_start_popup": "பயணம் தொடங்கும் இடம்",
    "feasibility_unrealistic_desc": "⚠️ {1} கி.மீ தொலைவுக்கு ({2} கி.மீ/நாள்) {0} நாட்கள் என்பது நடைமுறைக்கு சாத்தியமற்றது. அதிக சோர்வு மற்றும் விபத்து அபாயமின்றி சரக்கு லாரியால் இதை கடக்க முடியாது. பரிந்துரை: குறைந்தது {3} நாட்கள்.",
    "feasibility_demanding_desc": "⚠️ தினமும் {0} கி.மீ கடக்க 11 முதல் 13 மணிநேர தொடர் நெடுஞ்சாலை ஓட்டுநர் நேரம் தேவை. இரட்டை ஓட்டுநர்கள் அல்லது விரைவு டிரெய்லர்களுக்கு மட்டுமே பரிந்துரைக்கப்படுகிறது. நிலையான திட்டம்: {1} நாட்கள்.",
    "feasibility_optimal_desc": "✅ பாதுகாப்பான நடைமுறை சரக்கு போக்குவரத்து அட்டவணை. சராசரியாக {0} கி.மீ/நாள் (கட்டாய ஓய்வு இடைவெளிகளுடன் தினமும் ~8 முதல் 10 மணிநேரம்).",
    "feasibility_relaxed_desc": "ℹ️ மிகவும் தளர்வான அட்டவணை. சராசரியாக {0} கி.மீ/நாள். இந்த பயணத்தை {1} நாட்களில் எளிதாக முடிக்க முடியும்.",
    "advisory_mountain": "⚠️ மலை/காட் பகுதி: செங்குத்தான சரிவுகள், குறுகிய கொண்டை ஊசி வளைவுகள். இறங்குவதற்கு முன் இன்ஜின் பிரேக் மற்றும் பிரேக் ஆயிலை சரிபார்க்கவும். வளைவுகளில் முந்துவது தடைசெய்யப்பட்டுள்ளது.",
    "advisory_long_leg": "⚠️ நீண்ட தூர பயணம்: ஓட்டுநர் சோர்வு அபாயம் அதிகம். 4 மணிநேரத்திற்குப் பிறகு 30 நிமிட கட்டாய ஓய்வு எடுக்கவும். இரவு 11:00 மணிக்கு மேல் ஓட்டுவதைத் தவிர்க்கவும்.",
    "advisory_expressway": "🛣️ 4/6 வழி சுங்க நெடுஞ்சாலை: சீரான பயணம். ஃபாஸ்டாக் முன்னுரிமை வழிகளைப் பயன்படுத்தவும். நகர மையங்களைத் தவிர்த்து பைபாஸ் பாதையைப் பயன்படுத்தவும்.",
    "facility_rest_plaza": "சான்றளிக்கப்பட்ட நெடுஞ்சாலை ஓய்வு பிளாசா",
    "facility_truck_stop": "நெடுஞ்சாலை லாரி நிறுத்துமிடம் & எரிபொருள் நிலையம்",
    "facility_logistics_hub": "போக்குவரத்து நகரி தளவாட மையம்",
    "facility_dhaba_bay": "நெடுஞ்சாலை தாபா & கனரக வாகன பழுதுபார்க்கும் இடம்",
    "time_after_4hrs": "~4 மணிநேர ஓட்டுதலுக்குப் பிறகு",
    "amenities_plaza": "பார்க்கிங், உணவகம், சுத்தமான கழிப்பறைகள், 24/7 பாதுகாப்பு, டயர் பழுது",
    "amenities_stop": "டீசல் நிலையம், ஓட்டுநர் தங்குமிடம், கேண்டீன், மெக்கானிக் பட்டறை",
